export const html = "<header class=\"chrome\">\n  <button class=\"icon-btn glass\" aria-label=\"Close case study\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button>\n  <div class=\"right\">\n    <button class=\"icon-btn glass\" id=\"themeBtn\" aria-label=\"Switch theme\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"8\" cy=\"8\" r=\"5.5\"/><path d=\"M8 2.5v11A5.5 5.5 0 0 0 8 2.5z\" fill=\"currentColor\"/></svg></button>\n    <a class=\"pill-btn glass\" href=\"#next\"><span class=\"muted\">Next</span><span class=\"dot\" style=\"background:#38bdf8\"></span>CookAR</a>\n  </div>\n</header>\n\n<main class=\"wrap\">\n  <section class=\"hero-bleed\" id=\"cover\">\n    <!-- Hero motion on the real site: /cheffy_img/cheffy-hero-dark.html (the existing adapted mockup). Poster below. -->\n    <div class=\"hero-art ch-art\" aria-hidden=\"true\">\n      <div class=\"tab\">\n        <div class=\"tab-scr\" id=\"heroTab\">\n          <div class=\"ts-top\"><b>Kimchi Jjigae</b><span>Step 3/8</span></div>\n          <div class=\"ts-vid\"></div>\n          <div class=\"ts-ctrl\"><span>◀ Prev</span><span>Pause</span><span>Next ▶</span></div>\n          <div class=\"ts-macro\"><small>Elbow-bump mode</small><b>Next step →</b><span>Tap anywhere</span></div>\n        </div>\n      </div>\n    </div>\n    <div class=\"hero-media\" id=\"heroMedia\" data-src=\"/cheffy_img/cheffy-hero-dark.html\" aria-hidden=\"true\"></div>\n    <div class=\"hero-inner\">\n      <div class=\"hero-top\"><span class=\"tag on-img\">Cheffy</span><span class=\"t-small\">Adaptive cooking UI · early-stage AI product</span></div>\n          <div class=\"hero-grid\">\n            <h1 class=\"t-display\">When hands are full,<br>the screen adapts</h1>\n        <div class=\"hero-right\">\n          <p class=\"t-lead\"><b>I designed a cooking UI that switches to an elbow-sized target when voice and gestures fail.</b> Hand-wash interruptions dropped 91% and recipe completion rose 34% in beta.</p>\n          <div class=\"tags\"><span class=\"tag on-img\">Interaction Design</span><span class=\"tag on-img\">Adaptive UI</span><span class=\"tag on-img\">IoT</span></div>\n          <button class=\"btn-summary\" data-open-summary><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"2\" y=\"2\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"9\" y=\"2\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"2\" y=\"9\" width=\"5\" height=\"5\" rx=\"1\"/><rect x=\"9\" y=\"9\" width=\"5\" height=\"5\" rx=\"1\"/></svg>Read the 2-min summary <span class=\"sub\">5 slides</span></button>\n        </div>\n      </div>\n    </div>\n  </section>\n  <section class=\"hero\">\n    <div class=\"meta\">\n      <div><div class=\"t-caption\">Role</div><div class=\"t-label\">Founding Designer</div></div>\n      <div><div class=\"t-caption\">Timeline</div><div class=\"t-label\">8 weeks</div></div>\n      <div><div class=\"t-caption\">Domain</div><div class=\"t-label\">Cooking · IoT</div></div>\n      <div><div class=\"t-caption\">Tools</div><div class=\"t-label\">Figma · Cursor · SwiftUI · TF Lite</div></div>\n    </div>\n    <p class=\"t-caption\" style=\"margin-top:12px\">Product previews are adapted mockups while the product is in stealth.</p>\n\n    <div class=\"glance-head\"><span class=\"t-caption\">At a glance</span></div>\n    <div class=\"tldr\">\n      <div><div class=\"t-caption\">Problem</div><p class=\"t-small\"><b>Messy hands break cooking flow.</b> Every step meant wash, dry, tap, resume: 12–18 seconds lost per transition.</p></div>\n      <div><div class=\"t-caption\">Approach</div><p class=\"t-small\"><b>Read failure, then adapt.</b> When voice and gesture fail and the cook leans in, the bottom half of the screen becomes one elbow target.</p></div>\n      <div><div class=\"t-caption\">Outcome</div><p class=\"t-small\"><b>−91% hand-wash interruptions.</b> 97% elbow-tap success; +34% completion and +41% 7-day return in a 500-user beta.</p></div>\n    </div>\n\n    <div class=\"role reveal\">\n      <div class=\"role-head\"><span class=\"t-caption\">What I did</span><span class=\"t-caption\">Click to jump</span></div>\n      <div class=\"role-grid\">\n        <a href=\"#research\"><span class=\"t-label\">Field research</span><span class=\"t-caption\">12 cooks in-kitchen · 84 diary entries · sensor data</span></a>\n        <a href=\"#system\"><span class=\"t-label\">Designed the adaptive system</span><span class=\"t-caption\">Multi-signal state machine · elbow-bump mode</span></a>\n        <a href=\"#validation\"><span class=\"t-label\">Prototyped and tested</span><span class=\"t-caption\">3 prototype rounds · usability study n=18</span></a>\n        <a href=\"#outcome\"><span class=\"t-label\">Shipped to beta</span><span class=\"t-caption\">500 users · 4 weeks · live instrumentation</span></a>\n      </div>\n      <div class=\"team\"><span class=\"t-caption\">Role</span><span class=\"tag accent\">Founding designer · prototyper &amp; researcher</span></div>\n    </div>\n  </section>\n\n  <div class=\"case\">\n    <aside class=\"toc\" id=\"toc\" aria-label=\"Sections\">\n      <ol>\n        <li><a href=\"#context\"><span>01</span>Problem</a></li>\n        <li><a href=\"#research\"><span>02</span>Research</a></li>\n        <li><a href=\"#system\"><span>03</span>System</a></li>\n        <li><a href=\"#design\"><span>04</span>Design</a></li>\n        <li><a href=\"#validation\"><span>05</span>Validation</a></li>\n        <li><a href=\"#outcome\"><span>06</span>Outcome</a></li>\n        <li><a href=\"#reflection\"><span>07</span>Reflection</a></li>\n      </ol>\n    </aside>\n    <div>\n      <section class=\"sec\" id=\"context\">\n        <div class=\"eyebrow\"><span class=\"n\">01</span>Problem</div>\n        <h2 class=\"t-h2\">12 of 12 cooks broke flow to interact</h2>\n        <p class=\"t-body\">Recipe video apps assume clean, dry fingers. In reality cooks are elbow-deep in flour, raw meat or wet ingredients. Every interaction means <b>wash → dry → tap → resume</b>, adding 12–18 seconds per step. In our diary study, the most-logged frustration was \"wanted to tap but couldn't.\" 9 of the 12 cooks had already invented elbow taps.</p>\n\n        <figure class=\"breakout panel cascade reveal\" aria-label=\"The input failure cascade\">\n          <div class=\"chart-head\"><div><div class=\"t-label\">The input failure cascade</div><div class=\"t-caption\">Flour-covered hands, range hood running, trying to reach the next step</div></div></div>\n          <div class=\"casc\">\n            <div class=\"cs bad\"><span class=\"t-caption\">Voice</span><b>\"Hey, next step\"</b><span class=\"st\">Failed · 72dB noise</span></div>\n            <div class=\"arr\">→</div>\n            <div class=\"cs bad\"><span class=\"t-caption\">Gesture</span><b>Waves floury hand</b><span class=\"st\">Confidence 34% · occluded</span></div>\n            <div class=\"arr\">→</div>\n            <div class=\"cs ok\"><span class=\"t-caption\">Proximity</span><b>Leans toward iPad</b><span class=\"st\">Detected · &lt;30cm</span></div>\n            <div class=\"arr\">→</div>\n            <div class=\"cs on\"><span class=\"t-caption\">Mode switch</span><b>Elbow-bump mode</b><span class=\"st\">Active · 50% of screen</span></div>\n          </div>\n        </figure>\n        <p class=\"t-small\" style=\"margin-top:20px;max-width:640px\">An audit of leading recipe apps (NYT Cooking, Tasty, Paprika) confirmed the gap: every interaction model assumed clean hands and a quiet room.</p>\n      </section>\n\n      <section class=\"sec\" id=\"research\">\n        <div class=\"eyebrow\"><span class=\"n\">02</span>Research</div>\n        <h2 class=\"t-h2\">Understanding hands-occupied interaction</h2>\n        <p class=\"t-body\">I combined in-home observation to capture real behavior, sensor data to quantify environmental barriers, and a diary study to surface moments people couldn't articulate in interviews.</p>\n        <div class=\"methods reveal\">\n          <div><span class=\"t-caption\">Contextual inquiry</span><b class=\"mnum\">36 hours</b><p class=\"t-small\">12 home cooks observed over 3-hour sessions</p></div>\n          <div><span class=\"t-caption\">Sensor data</span><b class=\"mnum\">2,400+</b><p class=\"t-small\">Camera proximity and ambient noise across cooking phases</p></div>\n          <div><span class=\"t-caption\">Diary study</span><b class=\"mnum\">84 entries</b><p class=\"t-small\">7 days of \"moments I wanted to tap but couldn't\"</p></div>\n        </div>\n\n        <figure class=\"breakout panel noise reveal\" aria-label=\"Kitchen noise vs voice recognition threshold\">\n          <div class=\"chart-head\"><div><div class=\"t-label\">Kitchen noise vs. voice recognition</div><div class=\"t-caption\">Voice works below 50dB. Cooking rarely is.</div></div></div>\n          <div class=\"nbars\">\n            <div class=\"nb\"><span class=\"v\">35dB</span><i style=\"--h:35%\"></i><span class=\"l\">Idle</span></div>\n            <div class=\"nb\"><span class=\"v\">45dB</span><i style=\"--h:45%\"></i><span class=\"l\">Prep</span></div>\n            <div class=\"nb hot\"><span class=\"v\">55dB</span><i style=\"--h:55%\"></i><span class=\"l\">Chop</span></div>\n            <div class=\"nb hot\"><span class=\"v\">65dB</span><i style=\"--h:65%\"></i><span class=\"l\">Sauté</span></div>\n            <div class=\"nb hot\"><span class=\"v\">72dB</span><i style=\"--h:72%\"></i><span class=\"l\">Hood on</span></div>\n            <div class=\"nb hot\"><span class=\"v\">80dB</span><i style=\"--h:80%\"></i><span class=\"l\">Frying</span></div>\n            <div class=\"thr\" style=\"--t:50%\"><span>50dB voice threshold</span></div>\n          </div>\n        </figure>\n\n        <div class=\"stats-xl reveal\">\n          <div><span class=\"num\">68%</span><span class=\"t-small\">voice failure rate (range hood 65–80dB)</span></div>\n          <div><span class=\"num\">&lt;40%</span><span class=\"t-small\">gesture confidence with flour, mitts, utensils</span></div>\n          <div><span class=\"num accent\">9/12</span><span class=\"t-small\">already tried elbow taps, but 44px targets were too small</span></div>\n        </div>\n      </section>\n\n      <section class=\"statement reveal\" aria-label=\"Key insight\">\n        <p>Don't add another input. <em>Read the ones that are failing</em>, and adapt.</p>\n        <span class=\"t-caption\">The insight that shaped the system</span>\n      </section>\n\n      <section class=\"sec\" id=\"system\">\n        <div class=\"eyebrow\"><span class=\"n\">03</span>System</div>\n        <h2 class=\"t-h2\">An adaptive UI state machine</h2>\n        <p class=\"t-body\">A multi-signal trigger degrades gracefully from standard controls to one oversized target. All three conditions must hold, which kept false activations under 3%.</p>\n\n        <div class=\"breakout panel trig reveal\" id=\"trigDemo\">\n          <div class=\"sys-head\"><div><div class=\"t-label\">Trigger the mode switch</div><div class=\"t-caption\">Turn on all three signals</div></div><span class=\"tag\" id=\"trigState\">Default UI</span></div>\n          <div class=\"trig-grid\">\n            <div class=\"conds\">\n              <button class=\"cond\" data-c=\"v\" aria-pressed=\"false\"><span class=\"t-caption\">Voice input</span><b>Simulate failure</b><span class=\"cv\">OK</span></button>\n              <button class=\"cond\" data-c=\"g\" aria-pressed=\"false\"><span class=\"t-caption\">Gesture confidence</span><b>Drop below 40%</b><span class=\"cv\">92%</span></button>\n              <button class=\"cond\" data-c=\"p\" aria-pressed=\"false\"><span class=\"t-caption\">Proximity sensor</span><b>Lean in under 30cm</b><span class=\"cv\">80cm</span></button>\n              <div class=\"gate\"><span>AND</span><small id=\"gateTxt\">0 of 3 met · stay default</small></div>\n            </div>\n            <div class=\"tab small\"><div class=\"tab-scr\" id=\"demoTab\">\n              <div class=\"ts-top\"><b>Kimchi Jjigae</b><span>Step 3/8</span></div>\n              <div class=\"ts-vid\"></div>\n              <div class=\"ts-ctrl\"><span>◀ Prev</span><span>Pause</span><span>Next ▶</span></div>\n              <div class=\"ts-macro\"><small>Elbow-bump mode</small><b>Next step →</b><span>Tap anywhere</span></div>\n            </div></div>\n          </div>\n        </div>\n        <p class=\"t-caption fig-cap\">Transition: 400ms ease-out scale. Bottom 50% becomes a semi-transparent \"Next step\" button.</p>\n      </section>\n\n      <section class=\"sec\" id=\"design\">\n        <div class=\"eyebrow\"><span class=\"n\">04</span>Design</div>\n        <h2 class=\"t-h2\">Four decisions from field failures</h2>\n        <p class=\"t-body\">Each decision came from something we saw break: false activations in early prototypes, real elbow contact areas, users needing to see the recipe underneath, and accidental lock-in.</p>\n        <div class=\"dgrid reveal\">\n          <div class=\"tile\"><span class=\"t-caption\">Multi-signal AND gate</span><div class=\"cmpv\"><span class=\"dim\">Single trigger <b>23%</b></span><span class=\"on\">Multi-signal <b>&lt;3%</b></span></div><p class=\"t-small\">False positive rate</p></div>\n          <div class=\"tile\"><span class=\"t-caption\">Touch target, 120× larger</span><div class=\"cmpv\"><span class=\"dim\">Fingertip <b>8–12mm</b></span><span class=\"on\">Elbow zone <b>40–60mm</b></span></div><p class=\"t-small\">Half the screen, sized to measured elbow contact</p></div>\n          <div class=\"tile\"><span class=\"t-caption\">Semi-transparent overlay</span><div class=\"cmpv\"><span class=\"on\">85% gradient</span></div><p class=\"t-small\">The recipe video stays visible beneath the button</p></div>\n          <div class=\"tile\"><span class=\"t-caption\">Auto-revert</span><div class=\"cmpv\"><span class=\"on\">8s timeout</span></div><p class=\"t-small\">No proximity for 8s reverts; double-tap forces exit</p></div>\n        </div>\n      </section>\n\n      <section class=\"sec\" id=\"validation\">\n        <div class=\"eyebrow\"><span class=\"n\">05</span>Validation</div>\n        <h2 class=\"t-h2\">Testing with flour-covered hands</h2>\n        <p class=\"t-body\">18 participants cooked the same 8-step recipe twice: once with a standard UI, once with Cheffy's adaptive mode.</p>\n        <div class=\"compare reveal\">\n          <div class=\"tile\"><div class=\"head\"><span class=\"t-label\">Control · standard UI</span><span class=\"tag\">A</span></div>\n            <ol class=\"cmp-list\"><li>Standard 44px touch targets</li><li>Voice command only, not adaptive</li><li>Must wash hands to tap</li></ol></div>\n          <div class=\"tile ai\"><div class=\"head\"><span class=\"t-label\">Test · Cheffy adaptive</span><span class=\"tag accent\">B</span></div>\n            <ol class=\"cmp-list\"><li>Multi-signal trigger detection</li><li>Automatic elbow-bump mode</li><li>Half-screen macro target</li></ol></div>\n        </div>\n        <div class=\"deltas reveal\">\n          <div><div class=\"t-caption\">Hand-wash interruptions</div><div class=\"delta\"><s>6.2</s><span class=\"arr\">→</span><b>0.5</b></div><div class=\"t-small\">−91% per recipe</div></div>\n          <div><div class=\"t-caption\">Step transition time</div><div class=\"delta\"><s>15.2s</s><span class=\"arr\">→</span><b>3.3s</b></div><div class=\"t-small\">−78% average</div></div>\n        </div>\n        <div class=\"stats-xl c2 reveal\"><div><span class=\"num accent\">97%</span><span class=\"t-small\">elbow-tap success rate on the half-screen button</span></div><div><span class=\"num\">n=18</span><span class=\"t-small\">participants, within-subject</span></div></div>\n        <div class=\"quotes reveal\">\n          <figure><blockquote>\"I literally forgot I was using my elbow after the second step. It just felt natural. Lean in, bump, done.\"</blockquote><figcaption class=\"t-caption\">P7 · home cook, 3 years</figcaption></figure>\n          <figure><blockquote>\"The big button appearing when I got close was like the phone reading my mind.\"</blockquote><figcaption class=\"t-caption\">P12 · cooking instructor</figcaption></figure>\n        </div>\n      </section>\n\n      <section class=\"sec\" id=\"outcome\">\n        <div class=\"eyebrow\"><span class=\"n\">06</span>Outcome</div>\n        <h2 class=\"t-h2\">From concept to live beta</h2>\n        <p class=\"t-body\">After three prototype rounds and the usability study, adaptive mode shipped to a 500-user beta for 4 weeks. Removing hand-wash friction didn't just save time. It changed how people finished recipes.</p>\n        <div class=\"stats-xl reveal\">\n          <div><span class=\"num accent\">+34%</span><span class=\"t-small\">recipe completion</span></div>\n          <div><span class=\"num\">+22%</span><span class=\"t-small\">session duration</span></div>\n          <div><span class=\"num\">+41%</span><span class=\"t-small\">7-day return rate</span></div>\n        </div>\n        <div class=\"tech reveal\">\n          <div><span class=\"t-caption\">Trigger accuracy</span><b>97.2%</b></div>\n          <div><span class=\"t-caption\">False activation</span><b>2.8%</b></div>\n          <div><span class=\"t-caption\">Mode switch latency</span><b>&lt;400ms</b></div>\n        </div>\n        <div class=\"tl reveal\">\n          <div><span class=\"t-caption\">Wk 1–2</span><b>Contextual inquiry + diary study</b></div>\n          <div><span class=\"t-caption\">Wk 2–4</span><b>3 prototype rounds + usability study</b></div>\n          <div><span class=\"t-caption\">Wk 4–8</span><b>Beta rollout, 500 users</b></div>\n        </div>\n        <p class=\"t-caption\" style=\"margin-top:12px\">8 weeks, run in parallel.</p>\n      </section>\n\n      <section class=\"sec\" id=\"reflection\" style=\"border-bottom:0\">\n        <div class=\"eyebrow\"><span class=\"n\">07</span>Reflection</div>\n        <h2 class=\"t-h2\">What I learned</h2>\n        <div class=\"insight reveal\" style=\"margin-top:8px\"><p>The breakthrough wasn't adding input modalities. <em>It was listening to what was already failing.</em></p></div>\n        <div class=\"compare reveal\">\n          <div class=\"tile\"><div class=\"head\"><span class=\"t-label\">Old approach</span><span class=\"tag\">Add more</span></div><div class=\"cmp-body\"><p class=\"t-small\">Stack voice, gesture, gaze and touch and hope one works. Each layer adds latency, false positives and confusion.</p></div></div>\n          <div class=\"tile ai\"><div class=\"head\"><span class=\"t-label\">New approach</span><span class=\"tag accent\">Read failure</span></div><div class=\"cmp-body\"><p class=\"t-small\">Failure signals are the input. Two failed modalities plus proximity means the system already knows what to do. Zero new learning curve.</p></div></div>\n        </div>\n        <div class=\"list reveal\">\n          <div><span class=\"n\">01</span><div><div class=\"t-h3\">Context is the best input</div><p class=\"t-small\">When voice and gestures fail, the system already knows the user needs help.</p></div></div>\n          <div><span class=\"n\">02</span><div><div class=\"t-h3\">Body mechanics drive digital design</div><p class=\"t-small\">The half-screen button works because we measured real elbow contact areas (4.2 × 6.8cm) and forearm approach angles first.</p></div></div>\n        </div>\n      </section>\n    </div>\n  </div>\n\n  <a class=\"next\" id=\"next\" href=\"#\">\n    <div class=\"row\">\n      <div><div class=\"t-caption\" style=\"margin-bottom:8px\">Next project · CookAR</div><div class=\"t-h2\">Cooking safely with low vision</div></div>\n      <span class=\"arrow\" aria-hidden=\"true\">→</span>\n    </div>\n    <div class=\"panel nx-cookar\"><div class=\"nx-chip cyan\">UIST 2024 · Best Paper</div></div>\n  </a>\n</main>\n\n<div class=\"sum\" id=\"sum\" hidden role=\"dialog\" aria-modal=\"true\" aria-label=\"Summary mode\">\n  <div class=\"sum-card\">\n    <div class=\"sum-top\"><div class=\"sum-dots\" id=\"sumDots\"><i class=\"on\"></i><i></i><i></i><i></i><i></i></div><span class=\"t-caption sum-role\">Cheffy · Founding Designer · 8 weeks</span>\n      <button class=\"icon-btn\" id=\"sumClose\" aria-label=\"Close summary\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"><path d=\"M4 4l8 8M12 4l-8 8\"/></svg></button></div>\n    <div class=\"slide on\"><div class=\"s-l\"><span class=\"t-caption\">01 · Problem</span><p class=\"big\">Messy hands <em>break cooking flow.</em></p><p class=\"t-small\">Recipe apps assume clean fingers. Every step meant wash, dry, tap, resume: 12–18 seconds each time.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">Observed</span><p class=\"t-label\">12 of 12 cooks broke flow to interact</p></div><div><span class=\"t-caption\">Workaround</span><p class=\"t-label\">9 of 12 already tried elbow taps</p></div></div></div>\n    <div class=\"slide\"><div class=\"s-l\"><span class=\"t-caption\">02 · Research</span><p class=\"big\">Voice and gesture fail <em>exactly when needed.</em></p><p class=\"t-small\">36 hours of in-kitchen observation, 2,400+ sensor readings and 84 diary entries.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">Voice</span><p class=\"t-label\">68% failure · kitchens run 55–80dB</p></div><div><span class=\"t-caption\">Gesture</span><p class=\"t-label\">&lt;40% confidence with messy hands</p></div></div></div>\n    <div class=\"slide\"><div class=\"s-l\"><span class=\"t-caption\">03 · System</span><p class=\"big\">Read failure, <em>then adapt.</em></p><p class=\"t-small\">Voice fails + gesture &lt;40% + proximity &lt;30cm turns the bottom half of the screen into one elbow target in under 400ms.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">AND gate</span><p class=\"t-label\">False positives 23% → &lt;3%</p></div><div><span class=\"t-caption\">Target</span><p class=\"t-label\">120× larger, sized to elbows</p></div><div><span class=\"t-caption\">Safety</span><p class=\"t-label\">8s auto-revert</p></div></div></div>\n    <div class=\"slide\"><div class=\"s-l\"><span class=\"t-caption\">04 · Validation</span><p class=\"big\">Lean in, bump, done.</p><p class=\"t-small\">18 participants cooked the same recipe with standard and adaptive UI.</p></div>\n      <div class=\"s-r s-deltas\"><div><span class=\"t-caption\">Hand-wash interruptions</span><div class=\"delta\"><s>6.2</s><span class=\"arr\">→</span><b>0.5</b></div></div><p class=\"t-caption\">97% elbow-tap success · step time 15.2s → 3.3s</p></div></div>\n    <div class=\"slide\"><div class=\"s-l\"><span class=\"t-caption\">05 · Outcome</span><p class=\"big\">Shipped to a <em>500-user beta.</em></p><p class=\"t-small\">4 weeks of live instrumentation after 8 weeks from concept.</p></div>\n      <div class=\"s-r s-rows\"><div><span class=\"t-caption\">Recipe completion</span><p class=\"t-label\">+34%</p></div><div><span class=\"t-caption\">7-day return</span><p class=\"t-label\">+41%</p></div><div><span class=\"t-caption\">Trigger accuracy</span><p class=\"t-label\">97.2%</p></div></div></div>\n    <div class=\"sum-nav\"><span class=\"t-caption\" id=\"sumCount\">1 / 5</span><button class=\"icon-btn glass\" id=\"sumPrev\" aria-label=\"Previous slide\">←</button><button class=\"icon-btn glass\" id=\"sumNext\" aria-label=\"Next slide\">→</button></div>\n  </div>\n</div>";
